  `tahun` varchar(4) NOT NULL DEFAULT '2025',
  `opd_id` tinyint(3) unsigned DEFAULT NULL,
  `kode_program` varchar(20) DEFAULT NULL,
  `program` varchar(255) DEFAULT NULL,
  `rencana_aksi` longtext NOT NULL,
