  `target_satuan` varchar(50) DEFAULT NULL,
  `realisasi_nilai` decimal(15,2) DEFAULT NULL,
  `kendala` text DEFAULT NULL,
  `catatan` text DEFAULT NULL,
  `dokumentasi` varchar(2048) DEFAULT NULL COMMENT 'Link dokumentasi renaksi (GDrive/media lain), opsional',
  `created_by` bigint(20) unsigned DEFAULT NULL COMMENT 'User yang menambahkan renaksi (audit)',
  `ai_recommendation` text DEFAULT NULL COMMENT 'Hasil Analisis & Rekomendasi AI (per renaksi)',
  `indikator_1_id` tinyint(3) unsigned DEFAULT NULL,
  `indikator_2_id` tinyint(3) unsigned DEFAULT NULL,
  `indikator_3_id` tinyint(3) unsigned DEFAULT NULL,
  `indikator_4_id` tinyint(3) unsigned DEFAULT NULL,
  `status` enum('Tercapai','Hampir Tercapai','Tidak Tercapai','Belum diisi') NOT NULL DEFAULT 'Belum diisi',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `renaksi_programs_opd_id_foreign` (`opd_id`),
  KEY `renaksi_programs_indikator_1_id_foreign` (`indikator_1_id`),
  KEY `renaksi_programs_indikator_2_id_foreign` (`indikator_2_id`),
  KEY `renaksi_programs_indikator_3_id_foreign` (`indikator_3_id`),
  KEY `renaksi_programs_indikator_4_id_foreign` (`indikator_4_id`),
  KEY `renaksi_programs_tahun_index` (`tahun`),
  KEY `renaksi_programs_created_by_foreign` (`created_by`),
  CONSTRAINT `renaksi_programs_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `renaksi_programs_indikator_1_id_foreign` FOREIGN KEY (`indikator_1_id`) REFERENCES `indikators` (`id`) ON DELETE SET NULL,
