  CONSTRAINT `renaksi_programs_indikator_3_id_foreign` FOREIGN KEY (`indikator_3_id`) REFERENCES `indikators` (`id`) ON DELETE SET NULL,
  CONSTRAINT `renaksi_programs_indikator_4_id_foreign` FOREIGN KEY (`indikator_4_id`) REFERENCES `indikators` (`id`) ON DELETE SET NULL,
  CONSTRAINT `renaksi_programs_opd_id_foreign` FOREIGN KEY (`opd_id`) REFERENCES `opds` (`id`) ON DELETE SET NULL
